function initMobileMenu(){const e=document.querySelector(".nav-hamburger"),t=document.querySelector(".mobile-menu");if(!e||!t)return;const n=t.querySelectorAll(".nav-link");e.addEventListener("click",()=>{e.classList.toggle("open"),t.classList.toggle("open")}),n.forEach(n=>{n.addEventListener("click",()=>{e.classList.remove("open"),t.classList.remove("open")})})}function initSmoothScroll(){document.querySelectorAll('a[href^="#"]').forEach(e=>{e.addEventListener("click",t=>{const n=e.getAttribute("href");if("#"===n)return;const o=document.querySelector(n);if(!o)return;t.preventDefault();const i=document.querySelector(".header"),r=i?i.offsetHeight:0;window.scrollTo({top:o.offsetTop-r,behavior:"smooth"})})})}function initActiveNavHighlight(){const e=document.querySelectorAll("section[id]"),t=document.querySelectorAll(".nav-link");if(0===e.length||0===t.length)return;const n=new IntersectionObserver(e=>{e.forEach(e=>{if(e.isIntersecting){const n=e.target.getAttribute("id");t.forEach(e=>{e.classList.toggle("active",e.getAttribute("href")===`#${n}`)})}})},{rootMargin:"-20% 0px -80% 0px",threshold:0});e.forEach(e=>n.observe(e))}function initHeaderHideShow(){const e=document.querySelector(".header");if(!e)return;let t=window.scrollY,n=!1;window.addEventListener("scroll",()=>{n||(requestAnimationFrame(()=>{const o=window.scrollY;o>100&&o>t?e.classList.add("header--hidden"):e.classList.remove("header--hidden"),t=o,n=!1}),n=!0)},{passive:!0})}function initScrollAnimations(){const e=document.querySelectorAll(".fade-in");if(0===e.length)return;const t=new IntersectionObserver(e=>{e.forEach(e=>{e.isIntersecting&&(e.target.classList.add("visible"),t.unobserve(e.target))})},{threshold:.1,rootMargin:"0px 0px -50px 0px"});e.forEach(e=>t.observe(e))}document.addEventListener("DOMContentLoaded",()=>{initMobileMenu(),initSmoothScroll(),initActiveNavHighlight(),initHeaderHideShow(),initScrollAnimations()});